# compute latest by start_date if present, else end_date
from datetime import datetime

def parse_dt(s):
    if s is None:
        return None
    # accept formats like '2019-01-01T00:00:00'
    try:
        return datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        try:
            return datetime.strptime(s, '%Y-%m-%d')
        except Exception:
            return None

max_sub = None
max_dt = None
for r in subs:
    dt = parse_dt(r.get('start_date'))
    if dt is None:
        dt = parse_dt(r.get('end_date'))
    if dt is None:
        continue
    if max_dt is None or dt > max_dt:
        max_dt = dt
        max_sub = r
print('max_sub:', max_sub)
print('max_dt:', max_dt)

